{"query":"-- Distribution of buyer account age at time of refund (approx). Need buyer creation in events; use first purchase as proxy. Compute number of unique buyers with refunds and their average refunds per buyer.
SELECT COUNT(DISTINCT buyer_id) AS buyers_with_refunds, AVG(ref_count) AS avg_refunds_per_buyer
FROM (
  SELECT buyer_id, COUNT(*) AS ref_count FROM events WHERE event_type='refund' AND ts >= date('now','-90 days') GROUP BY buyer_id
);"}
